BEGIN
  INSERT INTO public.profile_private (id, email, gender, gstin, business_phone)
  SELECT r.id, r.email, r.gender, r.gstin, r.business_phone
  FROM jsonb_to_recordset(payload) AS r(id uuid, email text, gender text, gstin text, business_phone text)
  ON CONFLICT (id) DO UPDATE SET email = coalesce(EXCLUDED.email, profile_private.email), gender = coalesce(EXCLUDED.gender, profile_private.gender), gstin = coalesce(EXCLUDED.gstin, profile_private.gstin), business_phone = coalesce(EXCLUDED.business_phone, profile_private.business_phone),
    updated_at = now()
  WHERE (profile_private.email, profile_private.gender, profile_private.gstin, profile_private.business_phone)
        IS DISTINCT FROM (coalesce(EXCLUDED.email, profile_private.email), coalesce(EXCLUDED.gender, profile_private.gender), coalesce(EXCLUDED.gstin, profile_private.gstin), coalesce(EXCLUDED.business_phone, profile_private.business_phone));

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, email text, gender text, gstin text, business_phone text) JOIN public.profile_private p ON p.id = r.id
      WHERE (r.email IS NULL OR p.email = r.email) AND (r.gender IS NULL OR p.gender = r.gender) AND (r.gstin IS NULL OR p.gstin = r.gstin) AND (r.business_phone IS NULL OR p.business_phone = r.business_phone))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'private import: stored rows differ from the payload';
  END IF;
END
$import$;

