  FROM jsonb_to_recordset(payload) AS r(id uuid, likes_count int, views_count int, shares_count int)
  WHERE t.id = r.id AND (t.likes_count, t.views_count, t.shares_count) IS DISTINCT FROM (r.likes_count, r.views_count, r.shares_count);

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, likes_count int, views_count int, shares_count int) JOIN public.portfolio_items t ON t.id = r.id
      WHERE (t.likes_count, t.views_count, t.shares_count) = (r.likes_count, r.views_count, r.shares_count))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'portfolio counts import: stored rows differ from the payload';
  END IF;
END
